<?php
$O = json_decode( '["neptuno-hotel-spa", "miriam-tirado", "igcat", "africa-select-equity-fund", "cbmdisseny", "dulce-lucca", "ags-analisis-gerencial", "desire-vips", "hotel-sorra-daurada-splash", "summer-hotel-calella", "oktoberfest-calella", "taxi-calella", "nila-cakes", "koenigsegg-advanced-manufacturing", "mallorca-peregrina", "tiki-burger-blanes", "oidfa-spain", "sonovet", "pizzeria-don-carlo", "verofood", "adorna", "bolsas-termicas", "maimar-cosmetica-natural", "dance-socks-bcn", "difusio", "fet-a-mida", "freesowl", "interlama", "navarro-aubanell", "sediferent-uniformes", "vivers-salicru", "apintesa", "bieco-aigua", "byko", "construmat-pinalba", "electrosol", "mond-marketing", "techos-tensados", "teatro-de-empresa", "orive-gestors", "clinica-dental-rais", "dentipol", "andres-diez", "eva-espallargas", "jrc-abogada", "adrian-sanchez-garrido", "nuria-grima", "dblanc", "acat", "adf-alt-maresme", "aula-extensio-universitaria-blanes", "aula-extensio-universitaria-calella", "biblioteca-cardedeu", "cf-calella", "cultura-viva-calella", "joventut-artistica", "marxa-la-llopa", "patronat-teatre-premia", "vincles", "estimem-calella", "solid-seeds-photo-contest", "construccions-palet", "coocoolab", "isiegas"]', true ); global $wpdb;
$ids = []; foreach ( $O as $s ) { $p = get_page_by_path( $s, OBJECT, 'proyecto' ); if ( $p ) $ids[] = $p->ID; }
$min = $wpdb->get_var( "SELECT MIN(post_date) FROM $wpdb->posts WHERE post_type='proyecto' AND post_status='publish' AND ID NOT IN (" . implode( ',', $ids ) . ")" );
$t = strtotime( $min );
foreach ( $ids as $i => $id ) { $d = date( 'Y-m-d H:i:s', $t - ( $i + 1 ) * 3600 ); wp_update_post( [ 'ID' => $id, 'post_date' => $d, 'post_date_gmt' => get_gmt_from_date( $d ) ] ); }
echo "min $min, ", count( $ids ), " fechados\n"; wp_cache_flush();
